SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY A.MDF_DT DESC) AS LISTNUM, GRUP_CFY_CD, BLBR_UNQ_KY_VAL, BLBR_TITL_NM, FIRST_INPPR_ID, FIRST_INPPR_NM, FIRST_INPT_DT, UPDR_ID, UPDR_NM, MDF_DT, BLBR_CTT, TO_CHAR(MDF_DT, 'YYYY-MM-DD') AS FM_MDF_DT, (SELECT ATFL_ORSRC_NM || '.' || ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_BOARD_S' AND UNQ_NO = A.BLBR_UNQ_KY_VAL AND ATFL_ID = '1') ONAME1, (SELECT ATFL_GRUP_NM || '/' || ATFL_PHCL_NM || '.' || ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_BOARD_S' AND UNQ_NO = A.BLBR_UNQ_KY_VAL AND ATFL_ID = '1') FNAME1 FROM GE_MP_BOARD_S A WHERE DLT_YN = 'N'
AND GRUP_CFY_CD = #{GRUP_CFY_CD}
AND A.BLBR_TITL_NM = #{BLBR_TITL_NM}
ORDER BY MDF_DT DESC ) WHERE LISTNUM BETWEEN #{DISPSTART} AND #{DISPEND}

SELECT 
	COUNT(*) 
FROM GE_MP_BOARD_S A
WHERE GRUP_CFY_CD =  #{GRUP_CFY_CD}
  AND DLT_YN = 'N'

   AND A.BLBR_TITL_NM = #{BLBR_TITL_NM}
